-- mod-retail-professions: profession equipment, the parts the module itself needs.
--
-- mod_retail_professions_gear lists the items that go in profession equipment slots and what
-- they give (percentage points; skill_bonus in skill points). The gear items themselves come in
-- mod_retail_professions_2026_10_30_01.sql, which tools/build_gear_patch.py generates.
--
-- 90800-90811 are the skill bonus auras, one per profession, server-only (the client never sees
-- them): copies of Finkle's Skinner's equip bonus (16718), a hidden passive Mod Skill aura on
-- Alchemy, Blacksmithing, Enchanting, Engineering, Herbalism, Inscription, Jewelcrafting,
-- Leatherworking, Mining, Skinning, Tailoring and Cooking. The module sets the amount to the sum
-- of the slotted gear.

CREATE TABLE IF NOT EXISTS `mod_retail_professions_gear` (
    `entry`           INT UNSIGNED      NOT NULL COMMENT 'item_template entry',
    `skill`           SMALLINT UNSIGNED NOT NULL COMMENT 'skill line it serves',
    `kind`            TINYINT UNSIGNED  NOT NULL DEFAULT 0 COMMENT '0 tool, 1 accessory',
    `skill_bonus`     SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    `multicraft`      TINYINT UNSIGNED  NOT NULL DEFAULT 0,
    `resourcefulness` TINYINT UNSIGNED  NOT NULL DEFAULT 0,
    `speed`           TINYINT UNSIGNED  NOT NULL DEFAULT 0,
    `finesse`         TINYINT UNSIGNED  NOT NULL DEFAULT 0,
    `perception`      TINYINT UNSIGNED  NOT NULL DEFAULT 0,
    `deftness`        TINYINT UNSIGNED  NOT NULL DEFAULT 0,
    `counts_as`       INT UNSIGNED      NOT NULL DEFAULT 0 COMMENT 'item it stands in for as a recipe tool (Jeweler''s Kit 20815)',
    PRIMARY KEY (`entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DELETE FROM `spell_dbc` WHERE `ID` BETWEEN 90800 AND 90811;
